head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vs_G_BND_APPL_ID = ""; // 종목상세조회화면팝업에 쓰임
scwin.vs_G_BND_MKTACT_TP_CD = ""; // 종목상세조회화면팝업에 쓰임
scwin.vs_G_BND_MKTACT_TP_NM = ""; // 종목상세조회화면팝업에 쓰임
scwin.vs_G_BKBND_TP_CD = ""; // 종목상세조회화면팝업에 쓰임
scwin.vs_G_STRT_DD = ""; // 종목상세조회화면팝업에 쓰임
scwin.vs_G_STD_CD = ""; // 종목상세조회화면팝업에 쓰임
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용

scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        /**********************************************
         * 함수명   : gform > onload
         * 설명      : 화면 Onload
         ***********************************************/
        $c.bns.BnsPanelToGroupBox(panel_Top);

        // 시장조치
        const arrCid = [];
        arrCid.push({
            cid: '03057',
            cnm: 'cmb_MktStsGb'
        });
        $c.bns.fn_SetBnsComboToCode2("ULDBNS30400.xml", dts_Temp, arrCid, '전체');
        $c.pre_newlisting.fn_initSearchDate(edt_SDate, edt_EDate); // 신청일 기간
        const vCurDate = $c.ut.cGetToday("yyyymmdd");
        await scwin.getDate();
        edt_SDate.setValue(dts_getDate.getCellData(3, "CALND_DD"));
        edt_EDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));
        edt_SDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30400.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        /**********************************************
         * 함수명   : btn_Search > onclick
         * 설명      : 조회버튼 클릭
         ***********************************************/
        if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30400.btn_Search_onclick" });
    }
};

