/**
 * @method
 * @name tab_Main_OnSelChanged
 * @description tab Main On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tab_Main_OnSelChanged = async function(nIndex) {
    try {
        /**********************************************
         * 함수명   : tab_Main > OnSelChanged
         * 설명      : 텝 변경
         ***********************************************/
        // 전체
        if (nIndex === 1) {
            cmb_BndStsGb.CBData = "0^전체,1^미처리,2^처리중,3^처리완료,4^반송";
            cmb_BndStsGb.ResetData();
            txb_ISU_CD.setDisabled(false);
            btn_ISU_CD_SEARCH.setDisabled(false);
            btn_ISU_CD_SEARCH.setBackgroundImage("../img/btn_search.gif");
            rdo_DD_TP.setDisabled(false);
            // 개별종목

        } else if (nIndex === 2) {
            if (chk_SRI_BND_TP_CD.getValue() === "Y") {
                await $c.win.alert("[개별종목], [일괄상장종목] 탭은 ESG채권과 함께 사용 할 수 없습니다.");
                tab_Main.setSelectedTabIndex(1);
                return;
            }
            cmb_BndStsGb.CBData = "0^전체,1^미처리,2^처리중,3^처리완료,4^반송";
            cmb_BndStsGb.ResetData();
            txb_ISU_CD.setDisabled(false);
            btn_ISU_CD_SEARCH.setDisabled(false);
            btn_ISU_CD_SEARCH.setBackgroundImage("../img/btn_search.gif");
            rdo_DD_TP.setDisabled(false);
            // 일괄상장종목

        } else if (nIndex === 3) {
            if (chk_SRI_BND_TP_CD.getValue() === "Y") {
                await $c.win.alert("[개별종목], [일괄상장종목] 탭은 ESG채권과 함께 사용 할 수 없습니다.");
                tab_Main.setSelectedTabIndex(1);
                return;
            }
            cmb_BndStsGb.CBData = "0^전체,1^미처리,3^접수완료,4^반송";
            cmb_BndStsGb.ResetData();
            txb_ISU_CD.setValue("");
            txb_ISU_NM.setValue("");
            txb_ISU_CD.blur();
            txb_ISU_CD.setDisabled(true);
            btn_ISU_CD_SEARCH.setDisabled(true);
            btn_ISU_CD_SEARCH.setBackgroundImage("../img/btn_search_d.gif");
            rdo_DD_TP.setValue("1");
            rdo_DD_TP.setDisabled(true);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30400.tab_Main_OnSelChanged" });
    }
};

/**
 * @method
 * @name grd_List1_OnDblClick
 * @description grd_List1 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List1_OnDblClick = function(row, colid) {
    try {
        /**********************************************
         * 함수명   : grd_List1 > OnDblClick
         * 설명      : 팝업호출
         ***********************************************/
        if (row === 0) return;
        scwin.vs_G_BND_APPL_ID = dts_List1.getCellData(row, 'BND_APPL_ID'); // 종목상세조회화면팝업에 쓰임
        scwin.vs_G_BND_MKTACT_TP_CD = dts_List1.getCellData(row, 'BND_MKTACT_TP_CD'); // 종목상세조회화면팝업에 쓰임
        scwin.vs_G_BND_MKTACT_TP_NM = dts_List1.getCellData(row, 'MKT_NM'); // 종목상세조회화면팝업에 쓰임
        scwin.vs_G_BKBND_TP_CD = dts_List1.getCellData(row, 'BKBND_TP_CD'); // 종목상세조회화면팝업에 쓰임
        scwin.vs_G_STRT_DD = dts_List1.getCellData(row, 'APL_DT'); // 종목상세조회화면팝업에 쓰임
        scwin.vs_G_STRT_DD = scwin.vs_G_STRT_DD.replace(/-/g, "");
        scwin.vs_G_STD_CD = dts_List1.getCellData(row, 'ISU_CD'); // 종목상세조회화면팝업에 쓰임
        vs_G_ISUR_CD = dts_List1.getCellData(row, 'ISUR_CD'); // 발행기관코드

        if (dts_List1.getCellData(row, "SEARCH_GB_NM") === "일괄상장종목") {
            if (scwin.vs_G_BND_MKTACT_TP_CD === "112" || scwin.vs_G_BND_MKTACT_TP_CD === "122" || scwin.vs_G_BND_MKTACT_TP_CD === "132") {
                scwin.vs_G_BND_MKTACT_TP_CD = scwin.vs_G_BND_MKTACT_TP_CD + "Y";
            }
        }
        scwin.fn_GetPar = scwin.getCommonKey;
        $c.bns.fn_PopClsProcesStatIsuInfo(scwin.vs_G_BND_MKTACT_TP_CD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30400.grd_List1_OnDblClick" });
    }
};

/**
 * @method
 * @name grd_List2_OnDblClick
 * @description grd_List2 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List2_OnDblClick = function(row, colid) {
    try {
        /**********************************************
         * 함수명   : grd_List2 > OnDblClick
         * 설명      : 팝업호출
         ***********************************************/
        if (row === 0) return;
        scwin.vs_G_BND_APPL_ID = dts_List2.getCellData(row, 'BND_APPL_ID'); // 종목상세조회화면팝업에 쓰임
        scwin.vs_G_BND_MKTACT_TP_CD = dts_List2.getCellData(row, 'BND_MKTACT_TP_CD'); // 종목상세조회화면팝업에 쓰임
        scwin.vs_G_BND_MKTACT_TP_NM = dts_List2.getCellData(row, 'MKT_NM'); // 종목상세조회화면팝업에 쓰임
        scwin.vs_G_BKBND_TP_CD = dts_List2.getCellData(row, 'BKBND_TP_CD'); // 종목상세조회화면팝업에 쓰임
        scwin.vs_G_STRT_DD = dts_List2.getCellData(row, 'APL_DT'); // 종목상세조회화면팝업에 쓰임
        scwin.vs_G_STRT_DD = scwin.vs_G_STRT_DD.replace(/-/g, "");
        scwin.vs_G_STD_CD = dts_List2.getCellData(row, 'ISU_CD'); // 종목상세조회화면팝업에 쓰임
        vs_G_ISUR_CD = dts_List2.getCellData(row, 'ISUR_CD'); // 발행기관코드

        scwin.fn_GetPar = scwin.getCommonKey;
        $c.bns.fn_PopClsProcesStatIsuInfo(scwin.vs_G_BND_MKTACT_TP_CD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30400.grd_List2_OnDblClick" });
    }
};

/**
 * @method
 * @name grd_List3_OnDblClick
 * @description grd_List3 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List3_OnDblClick = function(row, colid) {
    try {
        /**********************************************
         * 함수명   : grd_List3 > OnDblClick
         * 설명      : 팝업호출
         ***********************************************/
        if (row === 0) return;
        scwin.vs_G_BND_APPL_ID = dts_List3.getCellData(row, 'BND_APPL_ID'); // 종목상세조회화면팝업에 쓰임
        scwin.vs_G_BND_MKTACT_TP_CD = dts_List3.getCellData(row, 'BND_MKTACT_TP_CD'); // 종목상세조회화면팝업에 쓰임
        scwin.vs_G_BND_MKTACT_TP_NM = dts_List3.getCellData(row, 'MKT_NM'); // 종목상세조회화면팝업에 쓰임
        scwin.vs_G_BKBND_TP_CD = dts_List3.getCellData(row, 'BKBND_TP_CD'); // 종목상세조회화면팝업에 쓰임
        scwin.vs_G_STRT_DD = dts_List3.getCellData(row, 'APL_DT'); // 종목상세조회화면팝업에 쓰임
        scwin.vs_G_STRT_DD = scwin.vs_G_STRT_DD.replace(/-/g, "");
        scwin.vs_G_STD_CD = dts_List3.getCellData(row, 'ISU_CD'); // 종목상세조회화면팝업에 쓰임
        if (scwin.vs_G_BND_MKTACT_TP_CD === "112" || scwin.vs_G_BND_MKTACT_TP_CD === "122" || scwin.vs_G_BND_MKTACT_TP_CD === "132") {
            scwin.vs_G_BND_MKTACT_TP_CD = scwin.vs_G_BND_MKTACT_TP_CD + "Y";
        }
        scwin.fn_GetPar = scwin.getCommonKey;
        $c.bns.fn_PopClsProcesStatIsuInfo(scwin.vs_G_BND_MKTACT_TP_CD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30400.grd_List3_OnDblClick" });
    }
};

/**
 * @method
 * @name chk_SRI_BND_TP_CD_onclick
 * @description chk_SRI_BND_TP_CD 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chk_SRI_BND_TP_CD_onclick = async function() {
    try {
        if (chk_SRI_BND_TP_CD.getValue() === "Y" && tab_Main.getSelectedTabIndex() !== 1) {
            await $c.win.alert("[개별종목], [일괄상장종목] 탭은 ESG채권과 함께 사용 할 수 없습니다.");
            chk_SRI_BND_TP_CD.setValue("N");
        }
        if (chk_SRI_BND_TP_CD.getValue() === "Y") {
            rdo_DD_TP.setValue("1");
            rdo_DD_TP.setDisabled(true);
        } else {
            rdo_DD_TP.setDisabled(false);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30400.chk_SRI_BND_TP_CD_onclick" });
    }
};

