/**
 * @method
 * @name search
 * @description 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    let vsTabSel = tab_Main.getSelectedTabIndex();

    // 전체조회
    if (vsTabSel === "1") {
        await scwin.search1();
        // 개별종목조회

    } else if (vsTabSel === "2") {
        await scwin.search2();
        // 일괄상장종목조회

    } else if (vsTabSel === "3") {
        await scwin.search3();
    }
};

/**
 * @method
 * @name excelDown
 * @description 정보를 excel로 다운 받는다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function() {
    let vsTabSel = tab_Main.getSelectedTabIndex();
    let voDtsList = null;
    let voGrid = null;
    const excelSheet = '';
    let today = $c.ut.cGetToday("yyyymmddhhmmss");
    let xls_path = $c.session.getExcelDownPath();

    // 전체조회
    if (vsTabSel === "1") {
        xls_path = xls_path + "채권처리현황(전체)_" + today + ".xlsx";
        voDtsList = dts_List1;
        voGrid = grd_List1;
        // 개별종목조회

    } else if (vsTabSel === "2") {
        xls_path = xls_path + "채권처리현황(개별)_" + today + ".xlsx";
        voDtsList = dts_List2;
        voGrid = grd_List2;
        // 일괄상장종목조회

    } else if (vsTabSel === "3") {
        xls_path = xls_path + "채권처리현황(일괄)_" + today + ".xlsx";
        voDtsList = dts_List3;
        voGrid = grd_List3;
    }
    if (voDtsList.getRowCount() > 0) {
        // 엑셀 로그
        $c.stf.doLogSave("ULDBNS30400.xml", SCREN_PROCS_TP_CD_07);
        voGrid.GridToOffice("sheet1", xls_path, 8, 0);
    } else {
        await $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};

/**
 * @method
 * @name excelDown3
 * @description 정보를 excel로 다운 받는다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown3 = async function() {
    let today = $c.ut.cGetToday("yyyymmddhhmmss");
    let xls_path = $c.session.getExcelDownPath() + "채권처리현황(일괄월별)_" + today + ".xlsx";
    if (dts_ListDet.getRowCount() > 0) {
        $c.stf.doLogSave("ULDBNS30400.xml", SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewOffice(grd_ListDetail, "sheet1", xls_path, 8, 0);
    } else {
        await $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};
